"""Binary Merkle tree over file chunks using only the Python stdlib (hashlib).

Conventions
-----------
- Files are split into CHUNK_SIZE (4 KiB) blocks; the last block may be short.
- Leaves are sha256 digests of the raw chunk bytes; internal nodes are
  sha256(left || right). When a level has an odd number of nodes, the last
  node is duplicated (Bitcoin-style).
- Empty file convention: an empty file has zero chunks, and its canonical
  root hash is defined as sha256(b"") (the digest of the empty byte string).
  verify(..., total_chunks=0) only succeeds for chunk_bytes == b"" and an
  empty proof list.
"""

import hashlib
import sys

CHUNK_SIZE = 4096

EMPTY_ROOT = hashlib.sha256(b"").hexdigest()


def _leaf(chunk_bytes):
    return hashlib.sha256(chunk_bytes).digest()


def _parent(left, right):
    return hashlib.sha256(left + right).digest()


def _levels(chunks):
    """Build all tree levels bottom-up. Returns [leaves, ..., root_level]."""
    if not chunks:
        return []
    level = [_leaf(c) for c in chunks]
    levels = [level]
    while len(level) > 1:
        if len(level) % 2 == 1:
            level = level + [level[-1]]  # duplicate last node when odd
        level = [_parent(level[i], level[i + 1]) for i in range(0, len(level), 2)]
        levels.append(level)
    return levels


def _chunks(path):
    with open(path, "rb") as f:
        while True:
            block = f.read(CHUNK_SIZE)
            if not block:
                break
            yield block


def _expected_depth(total_chunks):
    """Number of proof entries for a tree over total_chunks leaves."""
    if total_chunks <= 0:
        return 0
    d = 0
    n = total_chunks
    while n > 1:
        n = (n + 1) // 2  # odd levels shrink by duplicating the last node
        d += 1
    return d


def root_hash(path):
    """Hex-encoded Merkle root of the file at *path*."""
    chunks = list(_chunks(path))
    if not chunks:
        return EMPTY_ROOT
    return _levels(chunks)[-1][0].hex()


def num_chunks(path):
    """Number of chunks in the file at *path*."""
    return sum(1 for _ in _chunks(path))


def proof(path, chunk_index):
    """Audit path (list of 32-byte sibling hashes) for chunk *chunk_index*."""
    chunks = list(_chunks(path))
    if not chunks:
        raise ValueError("cannot build a proof for an empty file")
    if not 0 <= chunk_index < len(chunks):
        raise IndexError(
            f"chunk_index {chunk_index} out of range for {len(chunks)} chunks"
        )
    levels = _levels(chunks)
    audit, idx = [], chunk_index
    for level in levels[:-1]:
        sib = idx ^ 1
        # sibling beyond end of level means it was duplicated
        audit.append(level[sib] if sib < len(level) else level[idx])
        idx //= 2
    return audit


def verify(root, chunk_bytes, chunk_index, proof_list, total_chunks):
    """Return True iff *chunk_bytes* is chunk *chunk_index* of a file whose
    Merkle root is *root* (hex string) built over *total_chunks* chunks."""
    if total_chunks < 0:
        return False

    # Empty-file convention.
    if total_chunks == 0:
        return (
            chunk_bytes == b""
            and chunk_index == 0
            and list(proof_list) == []
            and root == EMPTY_ROOT
        )

    if not 0 <= chunk_index < total_chunks:
        return False
    if len(proof_list) != _expected_depth(total_chunks):
        return False

    h = _leaf(chunk_bytes)
    idx = chunk_index
    for sib in proof_list:
        if idx % 2 == 0:
            h = _parent(h, sib)
        else:
            h = _parent(sib, h)
        idx //= 2
    return h.hex() == root


# ----------------------------- CLI -----------------------------------------

def _cli(argv):
    usage = "usage:\n  python merkle.py root FILE\n  python merkle.py verify FILE INDEX"
    if len(argv) < 2:
        print(usage, file=sys.stderr)
        return 2
    cmd = argv[1]

    if cmd == "root":
        if len(argv) != 3:
            print(usage, file=sys.stderr)
            return 2
        print(root_hash(argv[2]))
        return 0

    if cmd == "verify":
        if len(argv) != 4:
            print(usage, file=sys.stderr)
            return 2
        path, index = argv[2], int(argv[3])
        chunks = list(_chunks(path))
        total = len(chunks)
        root = root_hash(path)
        if not 0 <= index < total:
            print(f"FAIL (index {index} out of range, file has {total} chunks)")
            return 1
        ok = verify(root, chunks[index], index, proof(path, index), total)
        print("OK" if ok else "FAIL")
        return 0 if ok else 1

    print(usage, file=sys.stderr)
    return 2


if __name__ == "__main__":
    sys.exit(_cli(sys.argv))

